function BackIcon() {
  return (
    <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className="h-4 w-4 shrink-0">
      <path d="M12.5 4.5l-6 5.5 6 5.5" />
    </svg>
  );
}

export default function SettingsView({
  categories,
  currency,
  username,
  email,
  wallets,
  expenses,
  remaining,
  activitiesDefaultWalletId,
  githubLinked,
  githubError,
}: {
  categories: CategoryOption[];
  currency: string;
  username: string;
  email: string | null;
  wallets: WalletOption[];
  expenses: Expense[];
  remaining: number;
  /** Which wallet Activities' balance card is scoped to by default; null means "All wallets". */
  activitiesDefaultWalletId: number | null;
  /** True right after a redirect back from /api/auth/github/link succeeded. */
  githubLinked?: boolean;
  /** Error code from a failed /api/auth/github/link redirect, if any. */
  githubError?: string;
}) {
  // Land straight in Account (rather than the Settings list) when arriving
  // fresh from a GitHub-link redirect, so the result is immediately visible
  // instead of requiring another tap to find it.
  const [panel, setPanel] = useState<Panel | null>(githubLinked || githubError ? "account" : null);
  const activeWallets = wallets.filter((w) => !w.archived);

  return (
    <CategoriesProvider categories={categories}>
    <WalletsProvider wallets={activeWallets}>
    <CurrencyProvider currency={currency}>
      <div className="mx-auto flex w-full max-w-4xl flex-1 flex-col px-3 pb-28 pt-3 sm:px-4 sm:pb-10">
        <PullToRefresh>
          <AppHeader />

          <main className="flex-1 px-1 py-6 sm:px-2">
            {panel ? (
              <div>
                {panel !== "dashboardWidgets" && (
                  <button
                    type="button"
                    onClick={() => setPanel(null)}
                    className="mb-4 flex items-center gap-1.5 text-sm font-semibold text-ink-soft transition hover:text-foreground"
                  >
                    <BackIcon />
                    Settings
                  </button>
                )}
                {(panel === "theme" || panel === "currency" || panel === "tags" || panel === "calendar") && (
                  <h2 className="mb-5 font-display text-2xl text-foreground">{PANEL_TITLES[panel]}</h2>
                )}

                {panel === "account" && (
                  <AccountPanel
                    initialUsername={username}
                    initialEmail={email}
                    githubLinked={githubLinked}
                    githubError={githubError}
                  />
                )}
                {panel === "permissions" && <PermissionsSettings hasEmail={Boolean(email)} />}
                {panel === "categories" && <CategoryManager categories={categories} />}
                {panel === "tags" && <TagManager />}
                {panel === "wallets" && (
                  <WalletManager wallets={wallets} initialActivitiesDefaultWalletId={activitiesDefaultWalletId} />
                )}
                {panel === "theme" && <ThemeSetting />}
                {panel === "currency" && <CurrencySettings />}
                {panel === "calendar" && <CalendarSettings />}
                {panel === "recurring" && <RecurringManager />}
                {panel === "budgets" && <BudgetManager />}
                {panel === "savingsGoals" && <SavingsGoalsManager />}
                {panel === "autoImport" && (
                  <div>
                    <ApiTokensManager />
                    <AutoImportInstructions />
                  </div>
                )}
                {panel === "errorReports" && <ErrorReportsPanel />}
                {panel === "dashboardWidgets" && (
                  <DashboardWidgetsSettings
                    expenses={expenses}
                    categories={categories}
                    remaining={remaining}
                    onDone={() => setPanel(null)}
                  />
                )}
              </div>
            ) : (
              <div>
                <h2 className="mb-5 font-display text-2xl text-foreground">Settings</h2>

                <SettingsSection title="App settings">
                  <SettingsListItem icon={<AccountIcon />} label="Account" onClick={() => setPanel("account")} />
                  <SettingsListItem icon={<ShieldIcon />} label="Permissions" onClick={() => setPanel("permissions")} />
                </SettingsSection>

                <SettingsSection title="Records">
                  <SettingsListItem icon={<GridIcon />} label="Manage categories" onClick={() => setPanel("categories")} />
                  <SettingsListItem icon={<HashIcon />} label="Manage tags" onClick={() => setPanel("tags")} />
                  <SettingsListItem icon={<WalletIcon />} label="Wallets" onClick={() => setPanel("wallets")} />
                  <ExportDataButton />
                  <ImportDataButton />
                </SettingsSection>

                <SettingsSection title="Budgeting">
                  <SettingsListItem icon={<RecurringIcon />} label="Recurring transactions" onClick={() => setPanel("recurring")} />
                  <SettingsListItem icon={<BudgetIcon />} label="Budgets" onClick={() => setPanel("budgets")} />
                  <SettingsListItem icon={<GoalIcon />} label="Savings goals" onClick={() => setPanel("savingsGoals")} />
                  <SettingsListItem icon={<AutoImportIcon />} label="Automatic import" onClick={() => setPanel("autoImport")} />
                </SettingsSection>

                <SettingsSection title="Display">
                  <SettingsListItem
                    icon={<DashboardWidgetsIcon />}
                    label="Customize dashboard"
                    onClick={() => setPanel("dashboardWidgets")}
                  />
                  <SettingsListItem icon={<CalendarIcon />} label="Calendar settings" onClick={() => setPanel("calendar")} />
                  <SettingsListItem icon={<SunMoonIcon />} label="Theme" onClick={() => setPanel("theme")} />
                  <SettingsListItem icon={<CoinIcon />} label="Currency" onClick={() => setPanel("currency")} />
                  <SettingsListItem icon={<GlobeIcon />} label="Language" badge="Coming soon" />
                </SettingsSection>

                <SettingsSection title="Support">
                  <SettingsListItem icon={<BookIcon />} label="Usage guide" href="/usage-guide" />
                  <SettingsListItem icon={<QuestionIcon />} label="FAQs" href="/faq" />
                  <SettingsListItem icon={<WrenchIcon />} label="Troubleshooting" href="/troubleshooting" />
                  <SettingsListItem icon={<WarningIcon />} label="Error log" onClick={() => setPanel("errorReports")} />
                  <SettingsListItem icon={<MailIcon />} label="Contact" href="/contact" />
                  <SettingsListItem icon={<FlagIcon />} label="Report an issue" href="/report-issue" />
                  <SettingsListItem icon={<ClockIcon />} label="Changelog" href="/changelog" />
                </SettingsSection>
              </div>
            )}

            <footer className="mt-12 flex flex-col items-center gap-2 border-t border-line pt-6 text-center text-xs text-ink-soft">
              <p>Tally v{APP_VERSION}</p>
              <p className="flex items-center gap-3">
                <Link href="/privacy" className="hover:text-foreground hover:underline">
                  Privacy Policy
                </Link>
                <span aria-hidden="true">·</span>
                <Link href="/terms" className="hover:text-foreground hover:underline">
                  Terms of Service
                </Link>
              </p>
            </footer>
          </main>
        </PullToRefresh>
      </div>
    </CurrencyProvider>
    </WalletsProvider>
    </CategoriesProvider>
  );
}
